mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
token = None
log = []

def get_token():
    global token
    while True:
        try:
            req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
            with urllib.request.urlopen(req, timeout=30) as r:
                token = json.load(r)["token"]; return
        except urllib.error.HTTPError as e:
            handle_err(e, "/token")
        except Exception as e:
            log.append(("exc", "/token", repr(e))); time.sleep(1)

def handle_err(e, path):
    body = e.read()[:300]
    log.append((e.code, path, dict(e.headers), body.decode(errors="replace")))
    if e.code == 429 or e.code == 503:
        ra = e.headers.get("Retry-After")
        try: wait = float(ra)
        except (TypeError, ValueError): wait = 2
        time.sleep(wait + 0.1)
    elif e.code == 401 or e.code == 403:
        get_token()
    else:
        time.sleep(1)

def get(path, allow404=False):
    if token is None: get_token()
    for attempt in range(200):
        try:
            req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + token})
            with urllib.request.urlopen(req, timeout=30) as r:
                raw = r.read()
                return json.loads(raw)
        except urllib.error.HTTPError as e:
            if e.code == 404 and allow404:
                log.append((404, path)); return None
            handle_err(e, path)
        except Exception as e:
            log.append(("exc", path, repr(e))); time.sleep(1)
    raise RuntimeError("gave up on " + path)

pages = []
path = "/orders?page=1"
while path:
    p = get(path)
    pages.append(p)
    print(path, p["page"], p["total_pages"], len(p["items"]), p["next"], file=sys.stderr)
    path = p["next"]

cust_ids = sorted({o["customer_id"] for p in pages for o in p["items"]})
customers = {}
for cid in cust_ids:
    customers[cid] = get("/customers/" + cid, allow404=True)

json.dump({"pages": pages, "customers": customers, "log": log}, open("/tmp/recon/raw.json", "w"), indent=1)
print("done", len(pages), len(customers), "errors", len(log), file=sys.stderr)
EOF
python3 -I /tmp/recon/fetch.py 2>&1 | tail -40

